#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, K, U;
    if (scanf("%d %d %d", &N, &K, &U) != 3) return 0;

    int **cards = (int **)malloc(N * sizeof(int *));
    for (int i = 0; i < N; i++) {
        cards[i] = (int *)malloc(K * sizeof(int));
        for (int j = 0; j < K; j++) {
            scanf("%d", &cards[i][j]);
        }
    }

    int *pos = (int *)malloc((U + 1) * sizeof(int));
    for (int i = 1; i <= U; i++) {
        int x;
        scanf("%d", &x);
        pos[x] = i;
    }

    int *finish = (int *)malloc(N * sizeof(int));
    int best = U + 1;

    for (int i = 0; i < N; i++) {
        int mx = 0;
        for (int j = 0; j < K; j++) {
            int p = pos[cards[i][j]];
            if (p > mx) mx = p;
        }
        finish[i] = mx;
        if (mx < best) best = mx;
    }

    int first = 1;
    for (int i = 0; i < N; i++) {
        if (finish[i] == best) {
            if (!first) printf(" ");
            printf("%d", i + 1);
            first = 0;
        }
    }
    printf("\n");

    for (int i = 0; i < N; i++) free(cards[i]);
    free(cards);
    free(pos);
    free(finish);

    return 0;
}
